B.azG=s(["\u6709\u622a\u6b62\u65e5\u7684\u9031\u671f\u9805\u76ee\u6703\u5728\u622a\u6b62\u65e5\u9694\u5929\u81ea\u52d5\u5f9e\u7ba1\u7406\u6e05\u55ae\u79fb\u9664\uff0c\u5df2\u5efa\u7acb\u7684\u8cc7\u6599\u4ecd\u6703\u4fdd\u7559\u3002","\u7121\u9650\u9031\u671f\u4e2d\u6b62\u5f8c\u6703\u4fdd\u7559\u5230\u6700\u5f8c\u751f\u6210\u65e5\u671f\uff0c\u4e26\u5728\u9694\u5929\u81ea\u52d5\u6e05\u9664\uff1b\u555f\u7528\u4e2d\u7684\u7121\u9650\u9031\u671f\u4e0d\u53d7\u5f71\u97ff\u3002","\u624b\u52d5\u8207\u5c0f\u55b5\u624b\u65b0\u589e\u6642\uff0c\u4fe1\u7528\u5361\u3001\u8cb8\u6b3e\u3001\u501f\u8cb8\u8207\u96fb\u4fe1\u4ee3\u4ed8\u7b49\u4ed8\u6b3e\u65b9\u5f0f\u6703\u81ea\u52d5\u5206\u985e\u70ba\u9810\u4ed8\u652f\u51fa\uff0c\u5be6\u969b\u9084\u6b3e\u4ecd\u70ba\u4e00\u822c\u652f\u51fa\u3002"],t.s)
B.avL=s(["Finite recurring rules are removed from management the day after their end date while generated records remain available.","Paused unlimited rules remain through their final generated date and are removed the next day; active unlimited rules remain unchanged.","Manual and helper-created entries using credit cards, loans, borrowing, or carrier billing are classified as advance expenses while repayments remain regular expenses."],t.s)
B.XG=new A.cv("v1.2.95+103","\u9031\u671f\u6e05\u7406\u8207\u9810\u4ed8\u652f\u51fa\u81ea\u52d5\u5206\u985e","Recurring-item cleanup and automatic advance-expense classification",B.azG,B.avL)
B.agQ=s(["\u8a18\u5e33\u3001\u884c\u7a0b\u8207\u5de5\u4f5c\u4efb\u52d9\u53ef\u8a2d\u5b9a\u6bcf\u65e5\u3001\u6bcf 2 \u81f3 10 \u5929\u6216\u6bcf\u6708\u6307\u5b9a\u65e5\u671f\u91cd\u8907\u3002","\u53ef\u8a2d\u5b9a\u622a\u6b62\u65e5\u671f\u6216\u7121\u9650\u671f\u57f7\u884c\uff0c\u4e26\u80fd\u5f9e\u9031\u671f\u9805\u76ee\u7ba1\u7406\u4e2d\u505c\u6b62\u6216\u6062\u5fa9\u3002","\u6bcf\u6708 15 \u65e5\u8d77\u6703\u9810\u5148\u5efa\u7acb\u4e0b\u500b\u6708\u8cc7\u6599\uff0c\u522a\u9664\u55ae\u6b21\u7d00\u9304\u5f8c\u4e0d\u6703\u518d\u6b21\u81ea\u52d5\u88dc\u56de\u3002"],t.s)
B.ak1=s(["Ledger entries, schedules, and work tasks can repeat daily, every 2 to 10 days, or on a selected monthly date.","Recurring items support an optional end date or no end date and can be paused or resumed from the account menu.","The next month is prepared from the 15th, while deleted individual occurrences stay excluded."],t.s)
